#include "ui.h"

#include <stdbool.h>

#include "lvgl.h"
#include "timer_core/format.h"

/*
 * Fonts for the elapsed time: Montserrat Medium, digits, ':', '+' and '-' only, generated by
 * lv_font_conv (command in each fonts/digits_*.c). "88:88" at 150 px is 434 px wide on the 448 px
 * screen; from 100:00 the time takes 120 px ("100:00" 427 px), from 1000:00 76 px. Each size is its
 * own font rather than a scaled row: scaling needs an LVGL layer buffer larger than LVGL's memory
 * pool, and a row that gets none is not drawn at all.
 */
extern const lv_font_t digits_150;
extern const lv_font_t digits_120;
/* Deviation line: 76 px, half the time's digit height; "-10:15" is about 197 px wide */
extern const lv_font_t digits_76;
#define UI_DEVIATION_FONT (&digits_76)
#define UI_SMALL_FONT (&lv_font_montserrat_28)

static const lv_font_t *const s_time_fonts[] = {&digits_150, &digits_120, &digits_76};
#define UI_TIME_FONTS (int)(sizeof s_time_fonts / sizeof s_time_fonts[0])

/*
 * The time is drawn one character per cell so it does not shift as digits change: every digit cell
 * is as wide as the widest digit, the ':' cell as wide as the colon. 12 cells hold any uint32_t
 * second count ("71582788:15").
 */
#define UI_TIME_CELLS 12

static lv_obj_t *s_screen;
static lv_obj_t *s_time;
static lv_obj_t *s_time_cells[UI_TIME_CELLS];
static tc_cell_widths_t s_cell_widths[UI_TIME_FONTS];
static int s_time_font = -1;
static lv_obj_t *s_deviation;
static lv_obj_t *s_disconnected;
static tc_view_t s_last;
static bool s_drawn;

static bool same_view(const tc_view_t *a, const tc_view_t *b)
{
    return a->seconds == b->seconds && a->background == b->background && a->foreground == b->foreground
           && a->show_deviation == b->show_deviation && a->deviation_s == b->deviation_s
           && a->show_disconnected == b->show_disconnected;
}

static lv_obj_t *create_label(const lv_font_t *font)
{
    lv_obj_t *label = lv_label_create(s_screen);
    lv_obj_set_style_text_font(label, font, 0);
    lv_label_set_text(label, "");
    return label;
}

static void create_time(void)
{
    for (int f = 0; f < UI_TIME_FONTS; f++) {
        int32_t digit_w = 0;
        for (uint32_t c = '0'; c <= '9'; c++) {
            int32_t w = (int32_t)lv_font_get_glyph_width(s_time_fonts[f], c, 0);
            if (w > digit_w) {
                digit_w = w;
            }
        }
        s_cell_widths[f].digit_w = digit_w;
        s_cell_widths[f].colon_w = (int32_t)lv_font_get_glyph_width(s_time_fonts[f], ':', 0);
    }

    s_time = lv_obj_create(s_screen);
    lv_obj_remove_style_all(s_time);
    /* lv_obj_create() makes it clickable, which would take taps and long presses from the screen */
    lv_obj_set_clickable(s_time, false);
    lv_obj_set_size(s_time, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_time, LV_FLEX_FLOW_ROW);
    lv_obj_set_scrollable(s_time, false);
    /* Font (set_time_text) and colour set on the row are inherited by the cells */
    s_time_font = -1;
    lv_obj_align(s_time, LV_ALIGN_CENTER, 0, -24);

    for (int i = 0; i < UI_TIME_CELLS; i++) {
        lv_obj_t *cell = lv_label_create(s_time);
        lv_obj_set_style_text_align(cell, LV_TEXT_ALIGN_CENTER, 0);
        lv_label_set_text(cell, "");
        lv_obj_set_hidden(cell, true);
        s_time_cells[i] = cell;
    }
}

static void set_time_text(const char *text)
{
    /* "100:00" and longer do not fit the screen at 150 px: take the largest font that fits */
    int font = tc_time_font_pick(text, UI_TIME_CELLS, s_cell_widths, UI_TIME_FONTS, lv_obj_get_width(s_screen));
    if (font != s_time_font) {
        lv_obj_set_style_text_font(s_time, s_time_fonts[font], 0);
        s_time_font = font;
    }

    const tc_cell_widths_t *widths = &s_cell_widths[font];
    int i = 0;
    for (; i < UI_TIME_CELLS && text[i] != '\0'; i++) {
        char one[2] = {text[i], '\0'};
        lv_label_set_text(s_time_cells[i], one);
        lv_obj_set_width(s_time_cells[i], text[i] == ':' ? widths->colon_w : widths->digit_w);
        lv_obj_set_hidden(s_time_cells[i], false);
    }
    for (; i < UI_TIME_CELLS; i++) {
        lv_obj_set_hidden(s_time_cells[i], true);
    }
}

void ui_create(void)
{
    s_screen = lv_screen_active();
    lv_obj_set_style_bg_opa(s_screen, LV_OPA_COVER, 0);
    lv_obj_set_style_pad_all(s_screen, 0, 0);
    lv_obj_set_scrollable(s_screen, false);

    create_time();

    s_deviation = create_label(UI_DEVIATION_FONT);
    lv_obj_align(s_deviation, LV_ALIGN_BOTTOM_MID, 0, -40);

    s_disconnected = create_label(UI_SMALL_FONT);
    lv_label_set_text(s_disconnected, LV_SYMBOL_USB " " LV_SYMBOL_CLOSE);
    lv_obj_align(s_disconnected, LV_ALIGN_TOP_RIGHT, -16, 16);

    s_drawn = false;
}

void ui_render(const tc_view_t *view)
{
    if (s_drawn && same_view(view, &s_last)) {
        return;
    }

    char text[24];
    lv_color_t fg = lv_color_hex(view->foreground);

    lv_obj_set_style_bg_color(s_screen, lv_color_hex(view->background), 0);

    if (tc_format_elapsed(text, sizeof text, view->seconds) > 0) {
        set_time_text(text);
    }
    lv_obj_set_style_text_color(s_time, fg, 0);

    lv_obj_set_hidden(s_deviation, !view->show_deviation);
    if (view->show_deviation && tc_format_deviation(text, sizeof text, view->deviation_s) > 0) {
        lv_label_set_text(s_deviation, text);
    }
    lv_obj_set_style_text_color(s_deviation, fg, 0);

    lv_obj_set_hidden(s_disconnected, !view->show_disconnected);
    lv_obj_set_style_text_color(s_disconnected, fg, 0);

    s_last = *view;
    s_drawn = true;
}
